// mintClientCredentialsToken POSTs grant_type=client_credentials to the
// token endpoint and returns the parsed token response.
func mintClientCredentialsToken(httpClient *http.Client, tokenURL, clientID, clientSecret string) (*tokenResponse, error) {
	form := url.Values{
		"grant_type": {"client_credentials"},
		// jamf-pro hand-fix: Jamf reads the client credentials from the form body.
		"client_id":     {clientID},
		"client_secret": {clientSecret},
	}
	if scope := resolveClientCredentialsScope(); scope != "" {
		form.Set("scope", scope)
	}
	req, err := http.NewRequest(http.MethodPost, tokenURL, strings.NewReader(form.Encode()))
	if err != nil {
		return nil, fmt.Errorf("building token request: %w", err)
	}
	req.Header.Set("Content-Type", "application/x-www-form-urlencoded")
	req.Header.Set("User-Agent", resolveClientCredentialsUserAgent())
	// jamf-pro hand-fix: no HTTP Basic; one client authentication method per request (RFC 6749 2.3).
	req, err = client.GuardTokenRequest(httpClient, req, []byte(form.Encode()))
	if err != nil {
		return nil, err
	}

	resp, err := cliutil.OAuthTokenHTTPClient(httpClient).Do(req)
	if err != nil {
		return nil, fmt.Errorf("calling token endpoint: %w", err)
	}
	defer resp.Body.Close()

	body, _ := io.ReadAll(resp.Body)
	if resp.StatusCode != http.StatusOK {
		return nil, fmt.Errorf("token endpoint returned HTTP %d: %s", resp.StatusCode, cliutil.SanitizeErrorBody(string(body)))
	}
	var tok tokenResponse
	if err := json.Unmarshal(body, &tok); err != nil {
		return nil, fmt.Errorf("parsing token response: %w", err)
	}
	if tok.AccessToken == "" {
		return nil, fmt.Errorf("token response missing access_token")
	}
	return &tok, nil
}

